CREATE FUNCTION public.mygrowth_current_owner_target(_training uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_mygrowth_reviewer() AND EXISTS(SELECT 1 FROM public.mygrowth_trainings t JOIN public.mygrowth_training_targets x ON x.training_id=t.id JOIN public.mygrowth_staff_registry s ON s.user_id=x.user_id JOIN public.profiles p ON p.user_id=s.user_id WHERE t.id=_training AND x.user_id=auth.uid() AND x.attendance_status='attended' AND s.active AND x.tenant_id=t.tenant_id AND x.branch_id=t.branch_id AND s.tenant_id=t.tenant_id AND s.branch_id=t.branch_id AND p.tenant_id=s.tenant_id AND p.department_id=s.branch_id) $$;
REVOKE ALL ON FUNCTION public.mygrowth_current_owner_target(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.mygrowth_current_owner_target(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.mygrowth_save_action_plan(_training_id uuid,_body text,_original_language text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN
IF NOT public.mygrowth_current_owner_target(_training_id) THEN RAISE EXCEPTION '현재 소속과 본인 참석을 확인하십시오.' USING ERRCODE='42501'; END IF;
IF nullif(btrim(_body),'') IS NULL OR length(_body)>5000 OR _original_language IS NULL OR _original_language NOT IN ('ko','en','ja','zh','yue') THEN RAISE EXCEPTION '필수 입력을 확인해 주십시오.' USING ERRCODE='22023'; END IF;
INSERT INTO public.mygrowth_action_plans(training_id,user_id,body,original_language) VALUES(_training_id,auth.uid(),btrim(_body),_original_language) ON CONFLICT(training_id,user_id) DO UPDATE SET body=EXCLUDED.body,original_language=EXCLUDED.original_language,updated_at=now() RETURNING id INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.mygrowth_my_action_plans() RETURNS TABLE(training_id uuid,session_kind text,title text,training_date date,branch_name text,plan_id uuid,body text,original_language text,updated_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT t.id,t.session_kind,t.title,t.training_date,d.name,a.id,a.body,a.original_language,a.updated_at FROM public.mygrowth_training_targets x JOIN public.mygrowth_trainings t ON t.id=x.training_id LEFT JOIN public.departments d ON d.id=t.branch_id LEFT JOIN public.mygrowth_action_plans a ON a.training_id=t.id AND a.user_id=x.user_id WHERE x.user_id=auth.uid() AND public.mygrowth_current_owner_target(t.id) ORDER BY t.training_date DESC,t.created_at DESC $$;
CREATE OR REPLACE FUNCTION public.mygrowth_scoped_action_plans() RETURNS TABLE(plan_id uuid,training_id uuid,session_kind text,title text,training_date date,branch_name text,employee_name text,body text,original_language text,updated_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,t.id,t.session_kind,t.title,t.training_date,d.name,coalesce(p.full_name,'이름 미등록'),a.body,a.original_language,a.updated_at FROM public.mygrowth_action_plans a JOIN public.mygrowth_trainings t ON t.id=a.training_id LEFT JOIN public.departments d ON d.id=t.branch_id LEFT JOIN public.profiles p ON p.user_id=a.user_id WHERE a.user_id<>auth.uid() AND public.mygrowth_staff_record_scope(a.user_id,t.id) AND public.mygrowth_followup_staff_scope(a.id) ORDER BY a.updated_at DESC $$;
CREATE OR REPLACE FUNCTION public.mygrowth_followup_detail(_plan_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE a record; staff boolean; BEGIN
IF NOT public.is_mygrowth_reviewer() THEN RAISE EXCEPTION '접근 권한이 없습니다.' USING ERRCODE='42501'; END IF;
SELECT * INTO a FROM public.mygrowth_action_plans WHERE id=_plan_id;
IF NOT FOUND THEN RAISE EXCEPTION '접근 권한이 없습니다.' USING ERRCODE='42501'; END IF;
staff=public.mygrowth_followup_staff_scope(a.id);
IF (a.user_id=auth.uid() AND NOT public.mygrowth_current_owner_target(a.training_id)) OR (a.user_id<>auth.uid() AND NOT staff) THEN RAISE EXCEPTION '현재 담당·참석 범위가 아닙니다.' USING ERRCODE='42501'; END IF;
RETURN jsonb_build_object('plan_updated_at',a.updated_at,'version',coalesce((SELECT max(h.version) FROM public.mygrowth_followup_audit h WHERE h.plan_id=a.id),0),'can_assess',staff AND EXISTS(SELECT 1 FROM public.mygrowth_training_targets x WHERE x.training_id=a.training_id AND x.user_id=a.user_id AND x.attendance_status='attended'),'history',coalesce((SELECT jsonb_agg(jsonb_build_object('version',h.version,'status',h.status,'note',h.note,'assessed_by',h.assessor_name,'assessed_at',h.assessed_at,'plan_body',h.plan_body,'plan_language',h.plan_language,'plan_updated_at',h.plan_updated_at) ORDER BY h.version DESC) FROM public.mygrowth_followup_audit h WHERE h.plan_id=a.id),'[]'::jsonb)); END $$;